[{"order":1,"type":"heading","text":"OS Module: Getting Operating System Information in Node.js"},{"order":2,"type":"paragraph","text":"The 'os' module in Node.js provides a number of operating system-related utility methods. It can be accessed using: 'const os = require("os");'. This tutorial will guide you through some of the most commonly used functions for retrieving OS information."},{"order":3,"type":"subheading","text":"Getting the Operating System Name"},{"order":4,"type":"paragraph","text":"The 'os.platform()' method returns a string identifying the operating system platform. Possible values include 'darwin', 'linux', 'win32', etc."},{"order":5,"type":"code","text":"const os = require('os');

console.log('Operating System:', os.platform());"},{"order":6,"type":"subheading","text":"Getting the Operating System Architecture"},{"order":7,"type":"paragraph","text":"The 'os.arch()' method returns a string identifying the operating system CPU architecture. Possible values include 'x64', 'arm64', 'ia32', etc."},{"order":8,"type":"code","text":"const os = require('os');

console.log('Architecture:', os.arch());"},{"order":9,"type":"subheading","text":"Getting the Operating System Release"},{"order":10,"type":"paragraph","text":"The 'os.release()' method returns a string specifying the operating system release."},{"order":11,"type":"code","text":"const os = require('os');

console.log('OS Release:', os.release());"},{"order":12,"type":"subheading","text":"Getting the Operating System Version"},{"order":13,"type":"paragraph","text":"The 'os.version()' method returns a string identifying the kernel version. Note that this method is only supported on certain operating systems."},{"order":14,"type":"code","text":"const os = require('os');

console.log('OS Version:', os.version());"},{"order":15,"type":"subheading","text":"Getting Hostname"},{"order":16,"type":"paragraph","text":"The 'os.hostname()' method returns the hostname of the operating system as a string."},{"order":17,"type":"code","text":"const os = require('os');

console.log('Hostname:', os.hostname());"},{"order":18,"type":"subheading","text":"Getting Uptime"},{"order":19,"type":"paragraph","text":"The 'os.uptime()' method returns the system uptime in seconds."},{"order":20,"type":"code","text":"const os = require('os');

console.log('Uptime:', os.uptime(), 'seconds');"},{"order":21,"type":"subheading","text":"Getting System Memory Information"},{"order":22,"type":"paragraph","text":"The 'os.totalmem()' method returns the total amount of system memory in bytes. The 'os.freemem()' method returns the amount of free system memory in bytes."},{"order":23,"type":"code","text":"const os = require('os');

console.log('Total Memory:', os.totalmem(), 'bytes');
console.log('Free Memory:', os.freemem(), 'bytes');"},{"order":24,"type":"subheading","text":"Getting CPU Information"},{"order":25,"type":"paragraph","text":"The 'os.cpus()' method returns an array of objects containing information about each CPU/core installed: model, speed (in MHz), and times (an object containing the number of milliseconds the CPU/core spent in: user, nice, sys, idle, and irq)."},{"order":26,"type":"code","text":"const os = require('os');

const cpus = os.cpus();
console.log('CPU Information:', cpus);"},{"order":27,"type":"subheading","text":"Getting Network Interfaces"},{"order":28,"type":"paragraph","text":"The 'os.networkInterfaces()' method returns an object containing a list of network interfaces that have been assigned a network address."},{"order":29,"type":"code","text":"const os = require('os');

const networkInterfaces = os.networkInterfaces();
console.log('Network Interfaces:', networkInterfaces);"},{"order":30,"type":"subheading","text":"Getting the End-of-Line Constant"},{"order":31,"type":"paragraph","text":"The 'os.EOL' property defines the operating-system-specific end-of-line marker. It is '\n' on POSIX and '\r\n' on Windows."},{"order":32,"type":"code","text":"const os = require('os');

console.log('End of Line:', os.EOL === '\n' ? 'Newline' : 'Carriage Return + Newline');"},{"order":33,"type":"subheading","text":"Getting the Temporary Directory"},{"order":34,"type":"paragraph","text":"The 'os.tmpdir()' method returns the operating system's default directory for temporary files."},{"order":35,"type":"code","text":"const os = require('os');

console.log('Temporary Directory:', os.tmpdir());"},{"order":36,"type":"paragraph","text":"This tutorial covered some of the most useful methods provided by the 'os' module in Node.js for retrieving operating system information. You can explore the official Node.js documentation for a complete list of available methods and properties."}]
